"""GENERATED by tools/make_sel2gc.py from dsa_sel2g.py: sel2g with static row classes (EngineConfig.dsa_row_classes):
each batch slot s scores its first 128 NG_s pages only (NG_s from the batch size's class layout), its score tile [128,
NG_s PPP], one stacked selection per class a program and each row compacted at its own width. A slot's tile entry
(p, c) is the row's pool p NT_s + c = page (p NG_s + g) PPP + j for any NG_s, the selection ties by that index, never
selects a pad, and the compaction's past-count entries are layout-free constants: the same lval / cpool / rows as sel2g
whenever every row's visible pools lie in its slot's first 128 NG_s pages (fits()). The engine's runner orders a decode
batch into the class slots, longest rows first, and sends a batch that does not fit to the next page bucket. With CW
(EngineConfig.dsa_row_classes_cw) the callers pass nloc fp32 [B, 1] as cand and the kernel builds each row's candidate
bias from it, so no [B, P] mask is built in XLA. Do not edit; regenerate."""

from __future__ import annotations

import zlib

import torch

from . import dsa_shell as dsh
from . import shell as SH

try:  # the Neuron venv
    import nki
    import nki.isa as nisa
    import nki.language as nl
except ImportError:
    nki = None


def parse(spec: str) -> dict:
    """A row-class layout spec, "B:NxG+NxG..,B:.." (e.g. "24:6x24+6x8+12x4,16:4x24+12x8") -> {B: (NG per slot, ...)}, the
    classes in the order given, which must be widest first (the runner's slot order: the longest rows first). Each
    class's count is even (slots alternate between the two LNC programs, so both get the same mix) and the counts add
    up to B. A batch size appears once: a repeat would silently replace the first layout. A class is at most 512 // PPP
    page groups wide: the kernel's widest score tile, NG PPP columns, holds at most 512 (dsa_sel2gc_kernel's NTM)."""
    out = {}
    for part in filter(None, (p.strip() for p in spec.split(","))):
        b, cls = part.split(":")
        if int(b) in out:
            raise ValueError(f"row classes {part!r}: batch size {int(b)} has a layout already")
        ngs = []
        for c in cls.split("+"):
            n, g = c.split("x")
            if int(n) % 2 or int(n) < 0 or int(g) < 1:
                raise ValueError(f"row classes {part!r}: {c!r} needs an even count and NG >= 1")
            if int(g) * dsh.PPP > 512:
                raise ValueError(f"row classes {part!r}: {c!r}'s score tile is {int(g) * dsh.PPP} columns, above the "
                                 f"kernel's 512 (NG at most {512 // dsh.PPP})")
            ngs += [int(g)] * int(n)
        if len(ngs) != int(b):
            raise ValueError(f"row classes {part!r}: {len(ngs)} slots for B {b}")
        if ngs != sorted(ngs, reverse=True):
            raise ValueError(f"row classes {part!r}: the classes must come widest first")
        out[int(b)] = tuple(ngs)
    return out


def _rc_ints(lay: dict) -> tuple:
    """The layouts as the kernel reads them: the trn2 NKI parser takes no dict keyed by an int, so at most 2 batch sizes
    of at most 4 runs of equal NG each, as module ints (B, then (count, NG) per run, 0 where absent), rebuilt in the
    kernel by _rc_layout."""
    items = sorted(lay.items())
    out = []
    for k in range(2):
        runs = []
        if k < len(items):
            for g in items[k][1]:
                if runs and runs[-1][1] == g:
                    runs[-1][0] += 1
                else:
                    runs.append([1, g])
        if len(items) > 2 or len(runs) > 4:
            raise ValueError(f"row classes {lay}: the kernel takes at most 2 batch sizes of at most 4 runs of equal NG")
        out.append(items[k][0] if k < len(items) else 0)
        for j in range(4):
            out += runs[j] if j < len(runs) else [0, 0]
    return tuple(out)


_RC_NAMES = ("RCB0", "RCN00", "RCG00", "RCN01", "RCG01", "RCN02", "RCG02", "RCN03", "RCG03",
             "RCB1", "RCN10", "RCG10", "RCN11", "RCG11", "RCN12", "RCG12", "RCN13", "RCG13")
# The layouts {B: (NG per slot)}, the module ints the kernel reads them through (_rc_layout) and each batch size's own
# revision term: set_layouts sets them together (the engine's set_decode_routes on every rank, from
# EngineConfig.dsa_row_classes, before the shard is built). Empty: no classes.
LAYOUTS: dict = {}
(RCB0, RCN00, RCG00, RCN01, RCG01, RCN02, RCG02, RCN03, RCG03,
 RCB1, RCN10, RCG10, RCN11, RCG11, RCN12, RCG12, RCN13, RCG13) = _rc_ints(LAYOUTS)
_LAYOUT_CRC: dict = {}
# The runner's guard (a name, set by the engine's runner): see takes().
RUNNER: str | None = None
# The candidate bias built in the kernel from nloc (EngineConfig.dsa_row_classes_cw): the callers pass cand = nloc fp32
# [B, 1] instead of where(arange(P) < nloc, 0.0, NEG_INF) fp32 [B, P] (an iota, a compare and a select on GpSimd once a
# step: ~557 us of a core's busy time at 24 rows on trn2), and the row setup makes M = (pool < nloc) - 1 in {+0.0, -1.0}
# from the row's own class iota, stage B adding (M x 1e30) + S. NEG_INF is the finite -1e30, fp32(1e30) x -1.0 is
# fp32(-1e30) bit for bit and +0.0 x 1e30 is +0.0, so the added term is the mask's bits and the add commutes. The body
# takes the form from cand's width, so a caller passing the [B, P] mask runs the mask's form unchanged.
CW = False


def set_layouts(spec: str) -> None:
    """LAYOUTS, the kernel's module ints and the per-batch-size revision terms from a layout spec (parse()); "" clears.
    The runner's guard (RUNNER) is cleared too: the runner built for these layouts installs it again."""
    global LAYOUTS, _LAYOUT_CRC, RUNNER
    lay = parse(spec)
    ints = _rc_ints(lay)
    LAYOUTS = lay
    RUNNER = None
    globals().update(zip(_RC_NAMES, ints))
    # computed here, not in traced code: layout_crc runs inside the traced decode call and Dynamo can't trace zlib.crc32
    _LAYOUT_CRC = {int(b): zlib.crc32(repr(sorted({int(b): ngs}.items())).encode()) for b, ngs in lay.items()}


if nki is not None:  # sel2gc's kernel: its own module and revision (REVGC), so no other call's key moves
    from .dsa_shell import _C2S_G, BF16, D, F32, I32, LPP, NEG_INF, PPP, VE, _c2s_waves, _ix_gather, _ix_row_setup
    from .dsa_shell import _ix_stage_a, _ix_stage_b, _sb, _select2s, _split3, _topk_consts, dma_static

    def _cwj(NT: int, j: int) -> int:
        """The width of the compaction's chunk j of a [128, NT] tile: 128, the last one NT - 128 j."""
        if NT - 128 * j < 128:
            return NT - 128 * j
        return 128

    def _compact2g(X, ii, bb):
        """The program's rows' local lists (row bb[r], the program's ii[r]-th) from their selections and score tiles, on
        the engines only: the k-th selected pool's partition from the partitions' inclusive counts, its partition row by
        a 0 / 1 matmul, its column by a prefix count of that row (a triangular matmul), its score by the same 0 / 1 matmul
        of the score tile's split3 pieces, its page from the page-group row's 8-bit digits. Every value exact. The rows'
        instructions are interleaved one op at a time (each engine runs its queue in order: one row's op fills the other's
        wait on the PE / PSUM), and each vector op runs once over the KT tiles of keep, with each element's arithmetic
        unchanged."""
        NT, NG, keep, KT = X["NT"], X["NG"], X["keep"], X["KT"]
        nch, cw = X["nch"], X["cw"]
        n = len(bb)
        s01, cnt, s01b, inc, incr, incb, pgi, t0i, t0f = [], [], [], [], [], [], [], [], []
        for r in range(n):
            s01.append(_sb((128, NT)))
            cnt.append(_sb((128, 1)))
            s01b.append(_sb((128, NT), BF16))
            inc.append(_sb((128, 1)))
            incr.append(_sb((1, 128)))
            incb.append(_sb((128, 128)))
            pgi.append(_sb((128, NG), I32))
            t0i.append(_sb((128, 1), I32))
            t0f.append(_sb((128, 1)))
        for r in range(n):  # the row's page groups and the page of pool 0 (pool_row of the entries past the count)
            dma_static(dst=pgi[r], src=X["ppg"].ap(pattern=[[X["B"] * X["NGM"], 128], [1, NG]],
                                                     offset=bb[r] * X["NGM"]))
            dma_static(dst=t0i[r], src=X["ppg"].ap(pattern=[[0, 128], [1, 1]], offset=bb[r] * X["NGM"]))
        for r in range(n):
            nisa.tensor_scalar_reduce(dst=s01[r], data=X["O"][:, ii[r], :], op0=nl.equal, operand0=0.0,
                                      reduce_op=nl.add, reduce_res=cnt[r])
        pin = []
        for r in range(n):  # inclusive count at each partition's end
            pin.append(nl.ndarray((128, 1), dtype=F32, buffer=nl.psum))
            nisa.nc_matmul(dst=pin[r], stationary=X["UPI"], moving=cnt[r], accumulate=False)
        for r in range(n):
            nisa.tensor_copy(dst=s01b[r], src=s01[r], engine=VE)
        for r in range(n):
            nisa.tensor_copy(dst=inc[r], src=pin[r], engine=VE)
        pit = []
        for r in range(n):
            pit.append(nl.ndarray((1, 128), dtype=F32, buffer=nl.psum))
            nisa.nc_matmul(dst=pit[r], stationary=inc[r], moving=X["IF"], accumulate=False)
        for r in range(n):
            nisa.tensor_copy(dst=incr[r], src=pit[r], engine=VE)
        pib = []
        for r in range(n):  # every partition holds the row of counts
            pib.append(nl.ndarray((128, 128), dtype=F32, buffer=nl.psum))
            nisa.nc_matmul(dst=pib[r], stationary=X["ONES1"], moving=incr[r], accumulate=False)
        for r in range(n):
            nisa.tensor_copy(dst=incb[r], src=pib[r], engine=VE)
        hi, mid, lo = [], [], []
        for r in range(n):
            h, m, lw = _split3(X["SALL"][ii[r]], 128, NT)
            hi.append(h)
            mid.append(m)
            lo.append(lw)
        dgt, tmp, tmf = [], [], []
        for r in range(n):  # the row's page groups as 8-bit digits
            dgt.append(_sb((128, 3, NG), BF16))
            tmp.append(_sb((128, NG), I32))
            tmf.append(_sb((128, NG)))
        for r in range(n):
            nisa.tensor_scalar(dst=tmp[r], data=pgi[r], op0=nl.right_shift, operand0=16, engine=VE)
            nisa.tensor_copy(dst=tmf[r], src=tmp[r], engine=VE)
            nisa.tensor_copy(dst=dgt[r][:, 0, :], src=tmf[r], engine=VE)
            nisa.tensor_scalar(dst=tmp[r], data=pgi[r], op0=nl.right_shift, operand0=8, op1=nl.bitwise_and,
                               operand1=255, engine=VE)
            nisa.tensor_copy(dst=tmf[r], src=tmp[r], engine=VE)
            nisa.tensor_copy(dst=dgt[r][:, 1, :], src=tmf[r], engine=VE)
            nisa.tensor_scalar(dst=tmp[r], data=pgi[r], op0=nl.bitwise_and, operand0=255, engine=VE)
            nisa.tensor_copy(dst=tmf[r], src=tmp[r], engine=VE)
            nisa.tensor_copy(dst=dgt[r][:, 2, :], src=tmf[r], engine=VE)
            nisa.tensor_copy(dst=t0f[r], src=t0i[r], engine=VE)
            nisa.tensor_scalar(dst=t0f[r], data=t0f[r], op0=nl.multiply, operand0=float(PPP), engine=VE)
        LV, CP = [], []
        for r in range(n):
            LV.append(_sb((128, KT)))
            CP.append(_sb((128, KT)))
        # every per-k-tile op on the vector engine runs once over the KT tiles ([128, KT, .]: the tile index t is a free
        # axis, the k's partition-wise scalars become [128, KT] tiles read through zero-stride access patterns); the PE's
        # matmuls stay per tile, into slices of one PSUM tile per group of TP tiles (TP NT <= 512 fp32: one bank)
        TP = min(KT, max(1, 512 // NT))
        IO = X["IO512"]
        KV = X["KV"]
        pk, m1, ex, dd, ohk = [], [], [], [], []
        for r in range(n):
            pk.append(_sb((128, KT)))  # the partition of the k-th selected pool: partitions whose inclusive count <= k
            m1.append(_sb((128, KT, 128)))
            ex.append(_sb((128, KT)))  # its exclusive count: the largest inclusive count <= k (0 if none)
            dd.append(_sb((128, KT)))
            ohk.append(_sb((128, KT, 128), BF16))  # [k, t, p] = (p == partition(k))
        kvp = KV.ap(pattern=[[KT, 128], [1, KT], [0, 128]], offset=0)
        for r in range(n):
            nisa.tensor_tensor(dst=m1[r], data1=incb[r].ap(pattern=[[128, 128], [0, KT], [1, 128]], offset=0), data2=kvp,
                               op=nl.less_equal, engine=VE)
        for r in range(n):
            nisa.tensor_reduce(dst=pk[r], op=nl.add, data=m1[r], axis=2)
        for r in range(n):
            nisa.tensor_tensor(dst=m1[r], data1=m1[r], data2=incb[r].ap(pattern=[[128, 128], [0, KT], [1, 128]], offset=0),
                               op=nl.multiply, engine=VE)
        for r in range(n):
            nisa.tensor_reduce(dst=ex[r], op=nl.maximum, data=m1[r], axis=2)
        for r in range(n):
            nisa.tensor_scalar(dst=pk[r], data=pk[r], op0=nl.minimum, operand0=127.0, engine=VE)
        for r in range(n):
            nisa.tensor_tensor(dst=dd[r], data1=KV, data2=ex[r], op=nl.subtract, engine=VE)
        for r in range(n):
            nisa.tensor_tensor(dst=ohk[r], data1=IO.ap(pattern=[[512, 128], [0, KT], [1, 128]], offset=0),
                               data2=pk[r].ap(pattern=[[KT, 128], [1, KT], [0, 128]], offset=0), op=nl.equal, engine=VE)
        oht, rs = [], []
        for r in range(n):
            oht.append(_sb((128, KT, 128), BF16))  # [p, t, k]
            rs.append(_sb((128, KT, NT), BF16))  # the k-th pool's partition row of selections
        TQ = min(KT, 4)  # the transposes' group: 128 columns a tile
        for g0 in range(0, KT, TQ):
            tg = min(TQ, KT - g0)
            pt = []
            for r in range(n):
                pt.append(nl.ndarray((128, TQ, 128), dtype=F32, buffer=nl.psum))
                for u in range(tg):
                    nisa.nc_matmul(dst=pt[r][:, u, :], stationary=ohk[r][:, g0 + u, :], moving=X["IB"], accumulate=False)
            for r in range(n):
                nisa.tensor_copy(dst=oht[r][:, g0:g0 + tg, :], src=pt[r][:, 0:tg, :], engine=VE)
        for g0 in range(0, KT, TP):
            tg = min(TP, KT - g0)
            prs = []
            for r in range(n):
                prs.append(nl.ndarray((128, TP, NT), dtype=F32, buffer=nl.psum))
                for u in range(tg):
                    nisa.nc_matmul(dst=prs[r][:, u, :], stationary=oht[r][:, g0 + u, :], moving=s01b[r], accumulate=False)
            for r in range(n):
                nisa.tensor_copy(dst=rs[r][:, g0:g0 + tg, :], src=prs[r][:, 0:tg, :], engine=VE)
        rts = []
        for r in range(n):
            rts.append(_sb((128, KT, nch * 128), BF16))  # row t's selections transposed, chunk j at [0:cw, t, j 128:]
        for t in range(KT):
            ptr = []
            for r in range(n):
                ptr.append(nl.ndarray((128, nch * 128), dtype=F32, buffer=nl.psum))
                for j in range(nch):
                    nisa.nc_matmul(dst=ptr[r][0:_cwj(NT, j), j * 128:(j + 1) * 128],
                                   stationary=rs[r][:, t, j * 128:j * 128 + _cwj(NT, j)],
                                   moving=X["IB"], accumulate=False)
            for r in range(n):
                nisa.tensor_copy(dst=rts[r][0:cw, t, :], src=ptr[r][0:cw, :], engine=VE)
        col, sv, pds = [], [], []
        for r in range(n):
            col.append(_sb((128, KT)))
            sv.append(_sb((128, KT)))
            pds.append(_sb((128, KT, 3 * NG)))
        # An accumulation group (a start, then accumulates) gets a PSUM tile of its own: several groups in slices of one
        # tile pass nki.simulate and compute wrong on trn2 (memory nki-psum-slice-accum-device-wrong; this kernel's psc
        # in that form gave 1,536 of 2,048 lval wrong on device, cd4aa18a). Lone starts into slices are exact.
        if nch == 1:
            for g0 in range(0, KT, TP):
                tg = min(TP, KT - g0)
                prc = []
                for r in range(n):  # inclusive count along the row: one lone start a tile, into slices of one tile
                    prc.append(nl.ndarray((128, TP, NT), dtype=F32, buffer=nl.psum))
                    for u in range(tg):
                        nisa.nc_matmul(dst=prc[r][:, u, :], stationary=rts[r][0:cw, g0 + u, 0:128],
                                       moving=X["UT"][0:cw, 0:NT], accumulate=False)
                for r in range(n):
                    m3 = _sb((128, TP, NT))
                    nisa.tensor_tensor(dst=m3[:, 0:tg, :], data1=prc[r][:, 0:tg, :],
                                       data2=dd[r].ap(pattern=[[KT, 128], [1, tg], [0, NT]], offset=g0),
                                       op=nl.less_equal, engine=VE)
                    nisa.tensor_reduce(dst=col[r][:, g0:g0 + tg], op=nl.add, data=m3[:, 0:tg, :], axis=2)
        else:
            for t in range(KT):
                prc = []
                for r in range(n):  # inclusive count along the row: nch accumulated chunks, a PSUM tile a k tile
                    prc.append(nl.ndarray((128, NT), dtype=F32, buffer=nl.psum))
                    for j in range(nch):
                        nisa.nc_matmul(dst=prc[r], stationary=rts[r][0:_cwj(NT, j), t, j * 128:(j + 1) * 128],
                                       moving=X["UT"][0:_cwj(NT, j), j * NT:(j + 1) * NT], accumulate=(j > 0))
                for r in range(n):
                    m3 = _sb((128, NT))
                    nisa.tensor_scalar_reduce(dst=m3, data=prc[r], op0=nl.less_equal, operand0=dd[r][:, t:t + 1],
                                              reduce_op=nl.add, reduce_res=col[r][:, t:t + 1])
        for r in range(n):
            nisa.tensor_scalar(dst=col[r], data=col[r], op0=nl.minimum, operand0=float(NT - 1), engine=VE)
        ohc = []
        for r in range(n):
            ohc.append(_sb((128, KT, NT)))
            nisa.tensor_tensor(dst=ohc[r], data1=IO.ap(pattern=[[512, 128], [0, KT], [1, NT]], offset=0),
                               data2=col[r].ap(pattern=[[KT, 128], [1, KT], [0, NT]], offset=0), op=nl.equal, engine=VE)
        for t in range(KT):
            psc = []
            for r in range(n):  # the partition row of scores: split3's pieces accumulated, a PSUM tile a k tile
                psc.append(nl.ndarray((128, NT), dtype=F32, buffer=nl.psum))
                nisa.nc_matmul(dst=psc[r], stationary=oht[r][:, t, :], moving=hi[r], accumulate=False)
                nisa.nc_matmul(dst=psc[r], stationary=oht[r][:, t, :], moving=mid[r], accumulate=True)
                nisa.nc_matmul(dst=psc[r], stationary=oht[r][:, t, :], moving=lo[r], accumulate=True)
            for r in range(n):
                scr = _sb((128, NT))
                nisa.tensor_tensor(dst=scr, data1=ohc[r][:, t, :], data2=psc[r], op=nl.multiply, engine=VE)
                nisa.tensor_reduce(dst=sv[r][:, t:t + 1], op=nl.add, data=scr, axis=1)
        for g0 in range(0, KT, TP):
            tg = min(TP, KT - g0)
            ppd = []
            for r in range(n):  # the partition's page digits, to SBUF (a vector op may not read both operands from PSUM)
                ppd.append(nl.ndarray((128, TP, 3 * NG), dtype=F32, buffer=nl.psum))
                for u in range(tg):
                    nisa.nc_matmul(dst=ppd[r][:, u, :], stationary=oht[r][:, g0 + u, :],
                                   moving=dgt[r].reshape((128, 3 * NG)), accumulate=False)
            for r in range(n):
                nisa.tensor_copy(dst=pds[r][:, g0:g0 + tg, :], src=ppd[r][:, 0:tg, :], engine=VE)
        pgf, ci, gi, ji, gf, jf, ohg, page, valid, ninf, lp, row = [], [], [], [], [], [], [], [], [], [], [], []
        for r in range(n):
            pgf.append(_sb((128, KT, NG)))
            ci.append(_sb((128, KT), I32))
            gi.append(_sb((128, KT), I32))
            ji.append(_sb((128, KT), I32))
            gf.append(_sb((128, KT)))
            jf.append(_sb((128, KT)))
            ohg.append(_sb((128, KT, NG)))
            page.append(_sb((128, KT)))
            valid.append(_sb((128, KT)))
            ninf.append(_sb((128, KT)))
            lp.append(_sb((128, KT)))
            row.append(_sb((128, KT)))
        for r in range(n):
            nisa.scalar_tensor_tensor(dst=pgf[r], data=pds[r][:, :, 0:NG], op0=nl.multiply, operand0=256.0, op1=nl.add,
                                      operand1=pds[r][:, :, NG:2 * NG])
        for r in range(n):
            nisa.scalar_tensor_tensor(dst=pgf[r], data=pgf[r], op0=nl.multiply, operand0=256.0, op1=nl.add,
                                      operand1=pds[r][:, :, 2 * NG:3 * NG])
        for r in range(n):
            nisa.tensor_copy(dst=ci[r], src=col[r], engine=VE)
        for r in range(n):
            nisa.tensor_scalar(dst=gi[r], data=ci[r], op0=nl.right_shift, operand0=LPP, engine=VE)
        for r in range(n):
            nisa.tensor_scalar(dst=ji[r], data=ci[r], op0=nl.bitwise_and, operand0=PPP - 1, engine=VE)
        for r in range(n):
            nisa.tensor_copy(dst=gf[r], src=gi[r], engine=VE)
        for r in range(n):
            nisa.tensor_copy(dst=jf[r], src=ji[r], engine=VE)
        for r in range(n):
            nisa.tensor_tensor(dst=ohg[r], data1=IO.ap(pattern=[[512, 128], [0, KT], [1, NG]], offset=0),
                               data2=gf[r].ap(pattern=[[KT, 128], [1, KT], [0, NG]], offset=0), op=nl.equal, engine=VE)
        for r in range(n):
            nisa.tensor_tensor(dst=ohg[r], data1=ohg[r], data2=pgf[r], op=nl.multiply, engine=VE)
        for r in range(n):
            nisa.tensor_reduce(dst=page[r], op=nl.add, data=ohg[r], axis=2)
        for r in range(n):
            nisa.tensor_tensor(dst=valid[r], data1=KV, data2=incb[r].ap(pattern=[[128, 128], [0, KT]], offset=127),
                               op=nl.less, engine=VE)
        # lval = valid ? score : NEG_INF; lp = valid ? partition NT + col : 0; rows = valid ? page 8 + j : page0 8
        for r in range(n):
            nisa.tensor_scalar(dst=ninf[r], data=valid[r], op0=nl.subtract, operand0=1.0, op1=nl.multiply,
                               operand1=-NEG_INF, engine=VE)
        for r in range(n):
            nisa.tensor_tensor(dst=sv[r], data1=sv[r], data2=valid[r], op=nl.multiply, engine=VE)
        for r in range(n):
            nisa.tensor_tensor(dst=LV[r], data1=sv[r], data2=ninf[r], op=nl.add, engine=VE)
        for r in range(n):
            nisa.scalar_tensor_tensor(dst=lp[r], data=pk[r], op0=nl.multiply, operand0=float(NT), op1=nl.add,
                                      operand1=col[r])
        for r in range(n):
            nisa.tensor_tensor(dst=lp[r], data1=lp[r], data2=valid[r], op=nl.multiply, engine=VE)
        for r in range(n):
            nisa.tensor_scalar(dst=CP[r], data=lp[r], op0=nl.multiply, operand0=float(X["A"]), op1=nl.add,
                               operand1=X["RK"], engine=VE)
        for r in range(n):
            nisa.scalar_tensor_tensor(dst=row[r], data=page[r], op0=nl.multiply, operand0=float(PPP), op1=nl.add,
                                      operand1=jf[r])
        for r in range(n):
            nisa.tensor_tensor(dst=row[r], data1=row[r], data2=t0f[r].ap(pattern=[[1, 128], [0, KT]], offset=0),
                               op=nl.subtract, engine=VE)
        for r in range(n):
            nisa.tensor_tensor(dst=row[r], data1=row[r], data2=valid[r], op=nl.multiply, engine=VE)
        for r in range(n):
            nisa.tensor_tensor(dst=row[r], data1=row[r], data2=t0f[r].ap(pattern=[[1, 128], [0, KT]], offset=0),
                               op=nl.add, engine=VE)
        bk = X["B"] * keep
        for r in range(n):  # out [3, B, keep]: lval, cpool, rows (fp32, exact), into the staging tile
            _one_stage(X, LV[r], bb[r] * keep, KT)
            _one_stage(X, CP[r], bk + bb[r] * keep, KT)
            _one_stage(X, row[r], 2 * bk + bb[r] * keep, KT)

    def _compact2sg(X, ii, bb):
        """_compact2 (cs 0) with the program's rows stacked (cs 1, served): the rows in groups of up to
        _C2S_G (consecutive in ii), and each of _compact2's per-row tiles one tile a group with the row as a free axis
        ([128, gs, .]; a row's [128, KT, .] tiles as [128, gs KT, .], row j's k tile t at slot s = j KT + t), so each
        vector op runs once a group where _compact2 issues it once a row. Every element's arithmetic is _compact2's (the
        same op, operands and dtypes; a per-row operand read through an access pattern with the group's strides), so
        lval, cpool and rows are its bits. The matmuls stay one a row and k tile; lone starts (accumulate=False) go into
        slices of one PSUM tile a group and chunk (at most 512 fp32 a partition: one bank), drained by one vector op.
        The accumulation groups (prc's chunks at nch > 1, psc's split3 pieces) keep a PSUM tile each and the ops that
        read them stay one a row and k tile (memory nki-psum-slice-accum-device-wrong); psc's products go into ohc (read
        nowhere else) and are summed once a group (ohc is one-hot: one nonzero term a sum, exact in any order). The
        selection count is a tensor_scalar then a tensor_reduce over the column axis (tensor_scalar_reduce sums every
        free axis; 0 / 1 sums are exact). _split3 and the HBM DMAs stay per row."""
        NT, NG, keep, KT = X["NT"], X["NG"], X["keep"], X["KT"]
        nch, cw = X["nch"], X["cw"]
        IO = X["IO512"]
        KV = X["KV"]
        n = len(bb)
        GQ = []  # the groups: (first row, rows)
        for g0 in range(0, n, _C2S_G):
            gs = min(_C2S_G, n - g0)
            for j in range(gs):
                assert ii[g0 + j] == ii[g0] + j  # a group's selections are consecutive in O
            GQ.append((g0, gs))
        nq = len(GQ)
        s01, cnt, s01b, inc, incr, incb, pgi, t0i, t0f = [], [], [], [], [], [], [], [], []
        for q in range(nq):
            gs = GQ[q][1]
            s01.append(_sb((128, gs, NT)))
            cnt.append(_sb((128, gs)))
            s01b.append(_sb((128, gs, NT), BF16))
            inc.append(_sb((128, gs)))
            incr.append(_sb((1, gs, 128)))
            incb.append(_sb((128, gs, 128)))
            pgi.append(_sb((128, gs, NG), I32))
            t0i.append(_sb((128, gs), I32))
            t0f.append(_sb((128, gs)))
        for q in range(nq):  # per row (its own HBM addresses), into the row's slice
            g0, gs = GQ[q]
            for j in range(gs):
                dma_static(dst=pgi[q][:, j, :],
                           src=X["ppg"].ap(pattern=[[X["B"] * X["NGM"], 128], [1, NG]],
                                           offset=bb[g0 + j] * X["NGM"]))
                dma_static(dst=t0i[q][:, j:j + 1], src=X["ppg"].ap(pattern=[[0, 128], [1, 1]],
                                                                  offset=bb[g0 + j] * X["NGM"]))
        for q in range(nq):  # the selection's 0 / 1, then its count a partition, per row
            g0, gs = GQ[q]
            nisa.tensor_scalar(dst=s01[q], data=X["O"][:, ii[g0]:ii[g0] + gs, :], op0=nl.equal, operand0=0.0,
                               engine=VE)
        for q in range(nq):
            nisa.tensor_reduce(dst=cnt[q], op=nl.add, data=s01[q], axis=2)
        pin = []
        for q in range(nq):  # inclusive count at each partition's end: a lone start a row, into slices of one tile
            gs = GQ[q][1]
            pin.append(nl.ndarray((128, gs), dtype=F32, buffer=nl.psum))
            for j in range(gs):
                nisa.nc_matmul(dst=pin[q][:, j:j + 1], stationary=X["UPI"], moving=cnt[q][:, j:j + 1],
                               accumulate=False)
        for q in range(nq):
            nisa.tensor_copy(dst=s01b[q], src=s01[q], engine=VE)
        for q in range(nq):
            nisa.tensor_copy(dst=inc[q], src=pin[q], engine=VE)
        pit = []
        for q in range(nq):
            gs = GQ[q][1]
            pit.append(nl.ndarray((1, gs, 128), dtype=F32, buffer=nl.psum))
            for j in range(gs):
                nisa.nc_matmul(dst=pit[q][:, j, :], stationary=inc[q][:, j:j + 1], moving=X["IF"], accumulate=False)
        for q in range(nq):
            nisa.tensor_copy(dst=incr[q], src=pit[q], engine=VE)
        pib = []
        for q in range(nq):  # every partition holds the row of counts
            gs = GQ[q][1]
            pib.append(nl.ndarray((128, gs, 128), dtype=F32, buffer=nl.psum))
            for j in range(gs):
                nisa.nc_matmul(dst=pib[q][:, j, :], stationary=X["ONES1"], moving=incr[q][:, j, :], accumulate=False)
        for q in range(nq):
            nisa.tensor_copy(dst=incb[q], src=pib[q], engine=VE)
        hi, mid, lo = [], [], []
        for r in range(n):
            h, m, lw = _split3(X["SALL"][ii[r]], 128, NT)
            hi.append(h)
            mid.append(m)
            lo.append(lw)
        dgt, tmp, tmf = [], [], []
        for q in range(nq):  # the rows' page groups as 8-bit digits: row j's [d0 | d1 | d2] at [:, j, :]
            gs = GQ[q][1]
            dgt.append(_sb((128, gs, 3 * NG), BF16))
            tmp.append(_sb((128, gs, 3 * NG), I32))
            tmf.append(_sb((128, gs, 3 * NG)))
        for q in range(nq):
            nisa.tensor_scalar(dst=tmp[q][:, :, 0:NG], data=pgi[q], op0=nl.right_shift, operand0=16, engine=VE)
            nisa.tensor_scalar(dst=tmp[q][:, :, NG:2 * NG], data=pgi[q], op0=nl.right_shift, operand0=8,
                               op1=nl.bitwise_and, operand1=255, engine=VE)
            nisa.tensor_scalar(dst=tmp[q][:, :, 2 * NG:3 * NG], data=pgi[q], op0=nl.bitwise_and, operand0=255,
                               engine=VE)
            nisa.tensor_copy(dst=tmf[q], src=tmp[q], engine=VE)
            nisa.tensor_copy(dst=dgt[q], src=tmf[q], engine=VE)
            nisa.tensor_copy(dst=t0f[q], src=t0i[q], engine=VE)
            nisa.tensor_scalar(dst=t0f[q], data=t0f[q], op0=nl.multiply, operand0=float(PPP), engine=VE)
        LV, CP = [], []
        for q in range(nq):
            LV.append(_sb((128, GQ[q][1] * KT)))
            CP.append(_sb((128, GQ[q][1] * KT)))
        pk, m1, ex, dd, ohk = [], [], [], [], []
        for q in range(nq):
            gs = GQ[q][1]
            pk.append(_sb((128, gs * KT)))  # the partition of the k-th selected pool (slot s = j KT + t)
            m1.append(_sb((128, gs, KT, 128)))
            ex.append(_sb((128, gs * KT)))  # its exclusive count
            dd.append(_sb((128, gs * KT)))
            ohk.append(_sb((128, gs * KT, 128), BF16))  # [k, s, p] = (p == partition(k))
        for q in range(nq):  # [k, j, t, c] = incb[k, j, c] <= KV[k, t]
            gs = GQ[q][1]
            nisa.tensor_tensor(dst=m1[q],
                               data1=incb[q].ap(pattern=[[gs * 128, 128], [128, gs], [0, KT], [1, 128]], offset=0),
                               data2=KV.ap(pattern=[[KT, 128], [0, gs], [1, KT], [0, 128]], offset=0),
                               op=nl.less_equal, engine=VE)
        for q in range(nq):
            nisa.tensor_reduce(dst=pk[q], op=nl.add, data=m1[q].reshape((128, GQ[q][1] * KT, 128)), axis=2)
        for q in range(nq):
            gs = GQ[q][1]
            nisa.tensor_tensor(dst=m1[q], data1=m1[q],
                               data2=incb[q].ap(pattern=[[gs * 128, 128], [128, gs], [0, KT], [1, 128]], offset=0),
                               op=nl.multiply, engine=VE)
        for q in range(nq):
            nisa.tensor_reduce(dst=ex[q], op=nl.maximum, data=m1[q].reshape((128, GQ[q][1] * KT, 128)), axis=2)
        for q in range(nq):
            nisa.tensor_scalar(dst=pk[q], data=pk[q], op0=nl.minimum, operand0=127.0, engine=VE)
        for q in range(nq):  # [k, j, t] = KV[k, t] - ex[k, j, t]
            gs = GQ[q][1]
            nisa.tensor_tensor(dst=dd[q].reshape((128, gs, KT)),
                               data1=KV.ap(pattern=[[KT, 128], [0, gs], [1, KT]], offset=0),
                               data2=ex[q].reshape((128, gs, KT)), op=nl.subtract, engine=VE)
        for q in range(nq):
            nsl = GQ[q][1] * KT
            nisa.tensor_tensor(dst=ohk[q], data1=IO.ap(pattern=[[512, 128], [0, nsl], [1, 128]], offset=0),
                               data2=pk[q].ap(pattern=[[nsl, 128], [1, nsl], [0, 128]], offset=0), op=nl.equal,
                               engine=VE)
        oht, rs = [], []
        for q in range(nq):
            oht.append(_sb((128, GQ[q][1] * KT, 128), BF16))  # [p, s, k]
            rs.append(_sb((128, GQ[q][1] * KT, NT), BF16))  # the k-th pool's partition row of selections
        WT = _c2s_waves(GQ, KT, 4)  # the transposes: 4 [128, 128] fp32 slots a PSUM tile (2 KB)
        for w in range(len(WT)):
            wv = WT[w]
            pt = []
            for i in range(len(wv)):
                q, c0, sz = wv[i]
                pt.append(nl.ndarray((128, sz, 128), dtype=F32, buffer=nl.psum))
                for u in range(sz):
                    nisa.nc_matmul(dst=pt[i][:, u, :], stationary=ohk[q][:, c0 + u, :], moving=X["IB"],
                                   accumulate=False)
            for i in range(len(wv)):
                q, c0, sz = wv[i]
                nisa.tensor_copy(dst=oht[q][:, c0:c0 + sz, :], src=pt[i], engine=VE)
        WS = _c2s_waves(GQ, KT, max(1, 512 // NT))  # [128, NT] fp32 slots a PSUM tile (sz NT <= 512: one bank)
        for w in range(len(WS)):
            wv = WS[w]
            prs = []
            for i in range(len(wv)):
                q, c0, sz = wv[i]
                prs.append(nl.ndarray((128, sz, NT), dtype=F32, buffer=nl.psum))
                for u in range(sz):
                    nisa.nc_matmul(dst=prs[i][:, u, :], stationary=oht[q][:, c0 + u, :],
                                   moving=s01b[q][:, (c0 + u) // KT, :], accumulate=False)
            for i in range(len(wv)):
                q, c0, sz = wv[i]
                nisa.tensor_copy(dst=rs[q][:, c0:c0 + sz, :], src=prs[i], engine=VE)
        rts = []
        for q in range(nq):  # slot s's selections transposed, chunk c at [0:cw, s, c 128:]
            rts.append(_sb((128, GQ[q][1] * KT, nch * 128), BF16))
        WR = _c2s_waves(GQ, KT, max(1, 512 // (nch * 128)))  # [128, nch 128] fp32 slots a PSUM tile
        for w in range(len(WR)):
            wv = WR[w]
            ptr = []
            for i in range(len(wv)):
                q, c0, sz = wv[i]
                ptr.append(nl.ndarray((128, sz, nch * 128), dtype=F32, buffer=nl.psum))
                for u in range(sz):
                    for c in range(nch):
                        nisa.nc_matmul(dst=ptr[i][0:_cwj(NT, c), u, c * 128:(c + 1) * 128],
                                       stationary=rs[q][:, c0 + u, c * 128:c * 128 + _cwj(NT, c)],
                                       moving=X["IB"],
                                       accumulate=False)
            for i in range(len(wv)):
                q, c0, sz = wv[i]
                nisa.tensor_copy(dst=rts[q][0:cw, c0:c0 + sz, :], src=ptr[i][0:cw, :, :], engine=VE)
        col, sv, pds = [], [], []
        for q in range(nq):
            col.append(_sb((128, GQ[q][1] * KT)))
            sv.append(_sb((128, GQ[q][1] * KT)))
            pds.append(_sb((128, GQ[q][1] * KT, 3 * NG)))
        # _compact2's rule (its note above nch == 1): an accumulation group gets a PSUM tile of its own, and the ops
        # that read one stay per row and k tile; lone starts into slices are exact
        if nch == 1:
            for w in range(len(WS)):
                wv = WS[w]
                prc = []
                for i in range(len(wv)):  # inclusive count along the row: a lone start a slot, into slices of one tile
                    q, c0, sz = wv[i]
                    prc.append(nl.ndarray((128, sz, NT), dtype=F32, buffer=nl.psum))
                    for u in range(sz):
                        nisa.nc_matmul(dst=prc[i][:, u, :], stationary=rts[q][0:cw, c0 + u, 0:128],
                                       moving=X["UT"][0:cw, 0:NT], accumulate=False)
                for i in range(len(wv)):
                    q, c0, sz = wv[i]
                    m3 = _sb((128, sz, NT))
                    nisa.tensor_tensor(dst=m3, data1=prc[i],
                                       data2=dd[q].ap(pattern=[[GQ[q][1] * KT, 128], [1, sz], [0, NT]], offset=c0),
                                       op=nl.less_equal, engine=VE)
                    nisa.tensor_reduce(dst=col[q][:, c0:c0 + sz], op=nl.add, data=m3, axis=2)
        else:
            for t in range(KT):
                prc = []
                for q in range(nq):  # inclusive count along the row: nch accumulated chunks, a PSUM tile a row and tile
                    for j in range(GQ[q][1]):
                        p_ = nl.ndarray((128, NT), dtype=F32, buffer=nl.psum)
                        for c in range(nch):
                            nisa.nc_matmul(dst=p_, stationary=rts[q][0:_cwj(NT, c), j * KT + t, c * 128:(c + 1) * 128],
                                           moving=X["UT"][0:_cwj(NT, c), c * NT:(c + 1) * NT],
                                           accumulate=(c > 0))
                        prc.append(p_)
                for q in range(nq):
                    for j in range(GQ[q][1]):
                        s = j * KT + t
                        m3 = _sb((128, NT))
                        nisa.tensor_scalar_reduce(dst=m3, data=prc[GQ[q][0] + j], op0=nl.less_equal,
                                                  operand0=dd[q][:, s:s + 1], reduce_op=nl.add,
                                                  reduce_res=col[q][:, s:s + 1])
        for q in range(nq):
            nisa.tensor_scalar(dst=col[q], data=col[q], op0=nl.minimum, operand0=float(NT - 1), engine=VE)
        ohc = []
        for q in range(nq):
            nsl = GQ[q][1] * KT
            ohc.append(_sb((128, nsl, NT)))
            nisa.tensor_tensor(dst=ohc[q], data1=IO.ap(pattern=[[512, 128], [0, nsl], [1, NT]], offset=0),
                               data2=col[q].ap(pattern=[[nsl, 128], [1, nsl], [0, NT]], offset=0), op=nl.equal,
                               engine=VE)
        for t in range(KT):
            psc = []
            for q in range(nq):  # the partition row of scores: split3's pieces accumulated, a PSUM tile a row and tile
                g0, gs = GQ[q]
                for j in range(gs):
                    p_ = nl.ndarray((128, NT), dtype=F32, buffer=nl.psum)
                    nisa.nc_matmul(dst=p_, stationary=oht[q][:, j * KT + t, :], moving=hi[g0 + j], accumulate=False)
                    nisa.nc_matmul(dst=p_, stationary=oht[q][:, j * KT + t, :], moving=mid[g0 + j], accumulate=True)
                    nisa.nc_matmul(dst=p_, stationary=oht[q][:, j * KT + t, :], moving=lo[g0 + j], accumulate=True)
                    psc.append(p_)
            for q in range(nq):  # _compact2's scr, in place in ohc (read nowhere else)
                g0, gs = GQ[q]
                for j in range(gs):
                    s = j * KT + t
                    nisa.tensor_tensor(dst=ohc[q][:, s, :], data1=ohc[q][:, s, :], data2=psc[g0 + j], op=nl.multiply,
                                       engine=VE)
        for q in range(nq):  # the scores: ohc one-hot, so one nonzero term a sum (exact in any order)
            nisa.tensor_reduce(dst=sv[q], op=nl.add, data=ohc[q], axis=2)
        # the partition's page digits, to SBUF (a vector op may not read both operands from PSUM): [128, 3 NG] fp32
        # slots a PSUM tile
        WD = _c2s_waves(GQ, KT, max(1, 512 // (3 * NG)))
        for w in range(len(WD)):
            wv = WD[w]
            ppd = []
            for i in range(len(wv)):
                q, c0, sz = wv[i]
                ppd.append(nl.ndarray((128, sz, 3 * NG), dtype=F32, buffer=nl.psum))
                for u in range(sz):
                    nisa.nc_matmul(dst=ppd[i][:, u, :], stationary=oht[q][:, c0 + u, :],
                                   moving=dgt[q][:, (c0 + u) // KT, :], accumulate=False)
            for i in range(len(wv)):
                q, c0, sz = wv[i]
                nisa.tensor_copy(dst=pds[q][:, c0:c0 + sz, :], src=ppd[i], engine=VE)
        pgf, ci, gi, ji, gf, jf, ohg, page, valid, ninf, lp, row = [], [], [], [], [], [], [], [], [], [], [], []
        for q in range(nq):
            nsl = GQ[q][1] * KT
            pgf.append(_sb((128, nsl, NG)))
            ci.append(_sb((128, nsl), I32))
            gi.append(_sb((128, nsl), I32))
            ji.append(_sb((128, nsl), I32))
            gf.append(_sb((128, nsl)))
            jf.append(_sb((128, nsl)))
            ohg.append(_sb((128, nsl, NG)))
            page.append(_sb((128, nsl)))
            valid.append(_sb((128, nsl)))
            ninf.append(_sb((128, nsl)))
            lp.append(_sb((128, nsl)))
            row.append(_sb((128, nsl)))
        for q in range(nq):
            nisa.scalar_tensor_tensor(dst=pgf[q], data=pds[q][:, :, 0:NG], op0=nl.multiply, operand0=256.0, op1=nl.add,
                                      operand1=pds[q][:, :, NG:2 * NG])
        for q in range(nq):
            nisa.scalar_tensor_tensor(dst=pgf[q], data=pgf[q], op0=nl.multiply, operand0=256.0, op1=nl.add,
                                      operand1=pds[q][:, :, 2 * NG:3 * NG])
        for q in range(nq):
            nisa.tensor_copy(dst=ci[q], src=col[q], engine=VE)
        for q in range(nq):
            nisa.tensor_scalar(dst=gi[q], data=ci[q], op0=nl.right_shift, operand0=LPP, engine=VE)
        for q in range(nq):
            nisa.tensor_scalar(dst=ji[q], data=ci[q], op0=nl.bitwise_and, operand0=PPP - 1, engine=VE)
        for q in range(nq):
            nisa.tensor_copy(dst=gf[q], src=gi[q], engine=VE)
        for q in range(nq):
            nisa.tensor_copy(dst=jf[q], src=ji[q], engine=VE)
        for q in range(nq):
            nsl = GQ[q][1] * KT
            nisa.tensor_tensor(dst=ohg[q], data1=IO.ap(pattern=[[512, 128], [0, nsl], [1, NG]], offset=0),
                               data2=gf[q].ap(pattern=[[nsl, 128], [1, nsl], [0, NG]], offset=0), op=nl.equal,
                               engine=VE)
        for q in range(nq):
            nisa.tensor_tensor(dst=ohg[q], data1=ohg[q], data2=pgf[q], op=nl.multiply, engine=VE)
        for q in range(nq):
            nisa.tensor_reduce(dst=page[q], op=nl.add, data=ohg[q], axis=2)
        for q in range(nq):  # [k, j, t] = KV[k, t] < incb[k, j, 127] (row j's count)
            gs = GQ[q][1]
            nisa.tensor_tensor(dst=valid[q].reshape((128, gs, KT)),
                               data1=KV.ap(pattern=[[KT, 128], [0, gs], [1, KT]], offset=0),
                               data2=incb[q].ap(pattern=[[gs * 128, 128], [128, gs], [0, KT]], offset=127),
                               op=nl.less, engine=VE)
        # lval = valid ? score : NEG_INF; lp = valid ? partition NT + col : 0; rows = valid ? page 8 + j : page0 8
        for q in range(nq):
            nisa.tensor_scalar(dst=ninf[q], data=valid[q], op0=nl.subtract, operand0=1.0, op1=nl.multiply,
                               operand1=-NEG_INF, engine=VE)
        for q in range(nq):
            nisa.tensor_tensor(dst=sv[q], data1=sv[q], data2=valid[q], op=nl.multiply, engine=VE)
        for q in range(nq):
            nisa.tensor_tensor(dst=LV[q], data1=sv[q], data2=ninf[q], op=nl.add, engine=VE)
        for q in range(nq):
            nisa.scalar_tensor_tensor(dst=lp[q], data=pk[q], op0=nl.multiply, operand0=float(NT), op1=nl.add,
                                      operand1=col[q])
        for q in range(nq):
            nisa.tensor_tensor(dst=lp[q], data1=lp[q], data2=valid[q], op=nl.multiply, engine=VE)
        for q in range(nq):
            nisa.tensor_scalar(dst=CP[q], data=lp[q], op0=nl.multiply, operand0=float(X["A"]), op1=nl.add,
                               operand1=X["RK"], engine=VE)
        for q in range(nq):
            nisa.scalar_tensor_tensor(dst=row[q], data=page[q], op0=nl.multiply, operand0=float(PPP), op1=nl.add,
                                      operand1=jf[q])
        for q in range(nq):  # [k, j, t] -= t0f[k, j] (the row's page-0 row)
            gs = GQ[q][1]
            nisa.tensor_tensor(dst=row[q].reshape((128, gs, KT)), data1=row[q].reshape((128, gs, KT)),
                               data2=t0f[q].ap(pattern=[[gs, 128], [1, gs], [0, KT]], offset=0), op=nl.subtract,
                               engine=VE)
        for q in range(nq):
            nisa.tensor_tensor(dst=row[q], data1=row[q], data2=valid[q], op=nl.multiply, engine=VE)
        for q in range(nq):
            gs = GQ[q][1]
            nisa.tensor_tensor(dst=row[q].reshape((128, gs, KT)), data1=row[q].reshape((128, gs, KT)),
                               data2=t0f[q].ap(pattern=[[gs, 128], [1, gs], [0, KT]], offset=0), op=nl.add,
                               engine=VE)
        bk = X["B"] * keep
        for q in range(nq):  # out [3, B, keep]: lval, cpool, rows (fp32, exact), a DMA a row from its slice
            g0, gs = GQ[q]
            for j in range(gs):
                o0 = bb[g0 + j] * keep
                _one_stage(X, LV[q][:, j * KT:(j + 1) * KT], o0, KT)
                _one_stage(X, CP[q][:, j * KT:(j + 1) * KT], bk + o0, KT)
                _one_stage(X, row[q][:, j * KT:(j + 1) * KT], 2 * bk + o0, KT)

    def _one_stage(X, T, off: int, KT: int):
        """T fp32 [128, KT] (out[off + p + 128 j] = T[p, j], sel2g's stores' layout) transposed on the PE into its slice
        of this program's staging tile STG [KT, 3 NP 128] (plane = off // keep // B, row b = off // keep % B, column
        (plane NP + b // NPG) 128); the program's one store after the compaction writes STG to out. Data movement only."""
        keep, B, NP, NPG, STG = X["keep"], X["B"], X["NP"], X["NPG"], X["STG"]
        pl = (off // keep) // B
        b = (off // keep) % B
        c0 = (pl * NP + b // NPG) * 128
        pt = nl.ndarray((KT, 128), dtype=F32, buffer=nl.psum)
        nisa.nc_transpose(dst=pt, data=T, engine=nisa.tensor_engine)
        nisa.tensor_copy(dst=STG[0:KT, c0:c0 + 128], src=pt, engine=VE)

    def _rc_layout(B: int):
        """LAYOUTS[B], the NG per slot, from the module ints (_rc_ints): the kernel's lookup, in forms the NKI parser
        takes."""
        ngs = []
        if B == RCB0:
            for _ in range(RCN00):
                ngs.append(RCG00)
            for _ in range(RCN01):
                ngs.append(RCG01)
            for _ in range(RCN02):
                ngs.append(RCG02)
            for _ in range(RCN03):
                ngs.append(RCG03)
        if B == RCB1:
            for _ in range(RCN10):
                ngs.append(RCG10)
            for _ in range(RCN11):
                ngs.append(RCG11)
            for _ in range(RCN12):
                ngs.append(RCG12)
            for _ in range(RCN13):
                ngs.append(RCG13)
        return ngs

    def _nbits(v: int) -> int:
        """v.bit_length(), in the kernel parser's subset."""
        n = 0
        for t in range(40):
            if (v >> t) > 0:
                n = t + 1
        return n

    def _rc_row_setup(X, i, b):
        """dsa_index._row_setup at slot b's own NG: its page-group row (NG_b of the NGM stored a slot), head weights and
        candidate bias (its first P_b pools, pool order): the mask's DMA, or under CW (pool < nloc) - 1 from the row's
        own class iota."""
        x = i % 3
        NGb = X["NGS"][b]
        NTb = X["NTS"][b]
        Hi = X["Hi"]
        nisa.dma_copy(dst=X["OF"][x][:, 0:NGb], src=X["ppg"].ap(pattern=[[X["B"] * X["NGM"], 128], [1, NGb]],
                                                                 offset=b * X["NGM"]))
        nisa.dma_copy(dst=X["WB"][x], src=X["wb"].ap(pattern=[[4 * Hi, 128], [1, 4 * Hi]], offset=b * 128 * 4 * Hi))
        if X["cwb"]:
            nisa.tensor_scalar(dst=X["C"][x][:, 0:NTb], data=X["IOCS"][b], op0=nl.less, operand0=X["NLB"][:, b:b + 1],
                               op1=nl.add, operand1=-1.0, engine=VE)  # (pool < nloc) - 1 in {+0.0, -1.0}
        else:
            nisa.dma_copy(dst=X["C"][x][:, 0:NTb], src=X["cand"].ap(pattern=[[NTb, 128], [1, NTb]], offset=b * X["P"]))

    def _rc_gather(X, k):
        """dsa_index._gather: the work item's 128 pages (page p NG_b + g on partition p), one indirect DMA."""
        i = X["G"][k][0]
        g = X["G"][k][2]
        kk = X["K"][k % X["nr"]]
        nisa.dma_copy(dst=kk, src=X["pkc"].ap(pattern=[[PPP * D, 128], [1, PPP * D]], offset=0,
                                             vector_offset=X["OF"][i % 3].ap(pattern=[[X["NGM"], 128], [1, 1]], offset=g),
                                             indirect_dim=0), dge_mode=X["dmode"])

    def _rc_stage_b(X, n):
        """dsa_index._stage_b at slot b's own NT: the scores, relu times w, the head sum; the row's last quarter adds its
        candidate bias (under CW (M x 1e30) + S, the mask's bits added) and stores the (unread) score copy."""
        i = X["QS"][n][1]
        b = X["QS"][n][2]
        g = X["QS"][n][3]
        h4 = X["QS"][n][4]
        qr = X["qr"]
        Hi = X["Hi"]
        NTb = X["NTS"][b]
        kt = X["KT"][n % qr]
        ps = X["PS"][n % qr]
        r = X["R"][n % qr]
        for j in range(4):
            nisa.nc_matmul(dst=ps[:, j * Hi:(j + 1) * Hi], stationary=kt[:, j * 128:(j + 1) * 128],
                           moving=X["QT"][:, b * Hi:(b + 1) * Hi], accumulate=False)
        nisa.scalar_tensor_tensor(dst=r, data=ps, op0=nl.maximum, operand0=0.0, op1=nl.multiply, operand1=X["WB"][i % 3])
        c = g * PPP + 4 * h4
        S = X["S"][i % 3]
        nisa.tensor_reduce(dst=S[:, c:c + 4], op=nl.add, data=r.reshape((128, 4, Hi)), axis=2)
        if g == X["NGS"][b] - 1 and h4 == PPP // 4 - 1:
            if X["cwb"]:
                nisa.scalar_tensor_tensor(dst=S[:, 0:NTb], data=X["C"][i % 3][:, 0:NTb], op0=nl.multiply, operand0=1e30,
                                          op1=nl.add, operand1=S[:, 0:NTb])
            else:
                nisa.tensor_tensor(dst=S[:, 0:NTb], data1=S[:, 0:NTb], data2=X["C"][i % 3][:, 0:NTb], op=nl.add, engine=VE)
            nisa.dma_copy(dst=X["out"].ap(pattern=[[NTb, 128], [1, NTb]], offset=b * X["P"]), src=S[:, 0:NTb])

    def _sel2gc(qT, wb, pkc, ppg, cand, identb, rank, keep: int, A: int, nbits: int, rbits: int, rev: int,
                dge: int, nr: int, qr: int, pf: int, cs: int, dbg: int, ngs):
        """sel2g's body with static row classes: sel2g's arguments (ppg int32 [128, B, NGM] with slot s's page groups at
        its own NG_s in its first NG_s columns: classed_ppg(); cand fp32 [B, P] as sel2g's, or under CW nloc fp32 [B, 1])
        and ngs, the NG per slot (the batch size's layout). Rows alternate between the programs as sel2g's; each program
        scores its rows' own groups in sel2g's static pipeline, selects one stacked _select2s per class (the rows of one
        NT), compacts each class's rows at its NT and stores its rows' lists in one DMA. nbits is unused (each class's
        own). Returns fp32 [3, B, keep] (sel2g's), one core barrier."""
        Dk, BH = qT.shape
        B = cand.shape[0]
        Hi = BH // B
        NGM = ppg.shape[2]
        PPP_ = pkc.shape[1] // Dk
        NTM = NGM * PPP_
        P = NTM * 128
        KT = keep // 128
        cwb = cand.shape[1] == 1  # CW: the candidate bias built from nloc
        assert Dk == D and PPP_ == PPP and wb.shape[2] == 4 * Hi and qr * 4 * Hi <= 512 and keep % 128 == 0
        assert len(ngs) == B and cand.shape[1] in (1, P) and NTM <= 512 and rbits > 1
        NGS = []
        NTS = []
        ngmin = NGM
        for s in range(B):
            assert 1 <= ngs[s] <= NGM and ngs[s] * PPP_ * 128 > keep and (ngs[s] * PPP_) % 8 == 0
            NGS.append(ngs[s])
            NTS.append(ngs[s] * PPP_)
            ngmin = min(ngmin, ngs[s])
        npg, pid = (nl.num_programs(axes=0), nl.program_id(axis=0)) if nl.program_ndim() != 0 else (1, 0)
        assert npg == 1 or B % 2 == 0, "LNC 2: an even batch"
        if npg > 1:
            for s in range(0, B, 2):
                assert ngs[s] == ngs[s + 1], "LNC 2: each slot pair one class (both programs the same mix)"
        out = nl.ndarray((3, B, keep), dtype=F32, buffer=nl.shared_hbm)  # lval, cpool, rows (exact integers < 2^24)
        scout = nl.ndarray((B, P), dtype=F32, buffer=nl.private_hbm)  # dsa_index's score DMA (unread)
        IB = _sb((128, 128), BF16)
        dma_static(dst=IB, src=identb)
        QT = _sb((D, BH), BF16)
        dma_static(dst=QT, src=qT)
        Kr, KTr, PTr, PSr, Rr, OFr, WBr, Sr, Cr = [], [], [], [], [], [], [], [], []
        for _ in range(qr):
            PTr.append(nl.ndarray((D, 512), dtype=F32, buffer=nl.psum))
        PSb = nl.ndarray((128, 512), dtype=F32, buffer=nl.psum)
        for i in range(qr):
            PSr.append(PSb[:, i * 4 * Hi:(i + 1) * 4 * Hi])
        for _ in range(nr):
            Kr.append(_sb((128, PPP * D), BF16))
        for _ in range(qr):
            KTr.append(_sb((D, 512), BF16))
            Rr.append(_sb((128, 4 * Hi)))
        for _ in range(3):
            OFr.append(_sb((128, NGM), I32))
            WBr.append(_sb((128, 4 * Hi)))
            Sr.append(_sb((128, NTM)))
            Cr.append(_sb((128, NTM)))
        NLB = None
        IOCS = []  # row s's own class iota (under CW)
        if cwb:
            NLB = _sb((128, B))  # every row's nloc on every partition (cand fp32 [B, 1], a stride-0 partition read)
            dma_static(dst=NLB, src=cand.ap(pattern=[[0, 128], [1, B]], offset=0))
            UNT = []  # each class's NT, first seen (lists: the device tracer's `in` takes a list, not a dict)
            UIO = []  # its pool iota p NT + j (float, exact below 2^24), the candidate bias's index
            for s in range(B):
                if NTS[s] not in UNT:
                    ioi = _sb((128, NTS[s]), I32)
                    nisa.iota(dst=ioi, pattern=[[1, NTS[s]]], offset=0, channel_multiplier=NTS[s])
                    iof = _sb((128, NTS[s]))
                    nisa.tensor_copy(dst=iof, src=ioi, engine=VE)
                    UNT.append(NTS[s])
                    UIO.append(iof)
            for s in range(B):
                for u in range(len(UNT)):
                    if UNT[u] == NTS[s]:
                        IOCS.append(UIO[u])
        rows = []
        for b in range(B):
            if b % npg == pid:
                rows.append(b)
        # this program's staging tile, [KT, plane x row x 128], every slice written by _one_stage
        STG = _sb((KT, 3 * max(1, len(rows)) * 128))
        # the program's classes (each distinct NT, first-seen order), each row's class and place in its stack
        CLS = []
        CROWS = []
        rcls = []
        rpos = []
        for i in range(len(rows)):
            nt = NTS[rows[i]]
            c = -1
            for j in range(len(CLS)):
                if CLS[j] == nt:
                    c = j
            if c < 0:
                CLS.append(nt)
                CROWS.append([])
                c = len(CLS) - 1
            rcls.append(c)
            rpos.append(len(CROWS[c]))
            CROWS[c].append(i)
        SALL = []
        for i in range(len(rows)):
            SALL.append(_sb((128, NTS[rows[i]])))
        SSC = []
        for c in range(len(CLS)):
            SSC.append(_sb((128, len(CROWS[c]), CLS[c])))  # the class's score tiles side by side (its stacked select)
        dmode = nisa.dge_mode.hwdge if dge == 2 else (nisa.dge_mode.swdge if dge == 1 else nisa.dge_mode.unknown)
        G = []
        for i in range(len(rows)):
            for g in range(NGS[rows[i]]):
                G.append((i, rows[i], g))
        QS = []
        for k in range(len(G)):
            for h4 in range(PPP // 4):
                QS.append((k, G[k][0], G[k][1], G[k][2], h4))
        PRE = min(nr - 1, pf, ngmin)  # page groups gathered ahead
        LAG = min(qr - 1, 2, PPP // 4)
        X = dict(B=B, NGM=NGM, NGS=NGS, NTS=NTS, Hi=Hi, P=P, nr=nr, qr=qr, dmode=dmode, ppg=ppg, wb=wb, cand=cand,
                 cwb=cwb, NLB=NLB, IOCS=IOCS, pkc=pkc, out=scout, IB=IB, QT=QT, OF=OFr, WB=WBr, S=Sr, C=Cr, K=Kr, KT=KTr,
                 PT=PTr, PS=PSr, R=Rr, G=G, QS=QS)
        if len(rows) > 0:
            _rc_row_setup(X, 0, rows[0])
            for k in range(min(PRE, len(G))):
                if G[k][2] == 0 and G[k][0] > 0:
                    _rc_row_setup(X, G[k][0], G[k][1])
                _rc_gather(X, k)
        for n in range(len(QS) + LAG):
            if n < len(QS):
                k = QS[n][0]
                if QS[n][4] == 0 and k + PRE < len(G):
                    if G[k + PRE][2] == 0:
                        _rc_row_setup(X, G[k + PRE][0], G[k + PRE][1])
                    _rc_gather(X, k + PRE)
                _ix_stage_a(X, n)
            if n >= LAG:
                m = n - LAG
                _rc_stage_b(X, m)
                if QS[m][3] == NGS[QS[m][2]] - 1 and QS[m][4] == PPP // 4 - 1:  # the row's scores are complete
                    i = QS[m][1]
                    nt = NTS[rows[i]]
                    nisa.tensor_copy(dst=SALL[i], src=Sr[i % 3][:, 0:nt], engine=VE)
                    nisa.tensor_copy(dst=SSC[rcls[i]][:, rpos[i], :], src=Sr[i % 3][:, 0:nt], engine=VE)
        if len(rows) > 0:
            # the classes' shared constants: the identities and triangles, iotas (exact integers in fp32)
            ji_ = _sb((128, 512), I32)
            nisa.iota(dst=ji_, pattern=[[1, 512]], offset=0, channel_multiplier=0)
            io512 = _sb((128, 512))
            nisa.tensor_copy(dst=io512, src=ji_, engine=VE)
            pi = _sb((128, 1), I32)
            nisa.iota(dst=pi, pattern=[[0, 1]], offset=0, channel_multiplier=1)
            pf_ = _sb((128, 1))
            nisa.tensor_copy(dst=pf_, src=pi, engine=VE)
            dd = _sb((128, 128))  # c - p
            nisa.tensor_scalar(dst=dd, data=io512[:, 0:128], op0=nl.subtract, operand0=pf_, engine=VE)
            IF = _sb((128, 128))
            nisa.tensor_scalar(dst=IF, data=dd, op0=nl.equal, operand0=0.0, engine=VE)
            UPI = _sb((128, 128))  # [p' <= p] at [p', p]
            nisa.tensor_scalar(dst=UPI, data=dd, op0=nl.greater_equal, operand0=0.0, engine=VE)
            ONES1 = _sb((1, 128))
            nisa.memset(dst=ONES1, value=1.0)
            kvi = _sb((128, KT), I32)
            nisa.iota(dst=kvi, pattern=[[128, KT]], offset=0, channel_multiplier=1)
            KV = _sb((128, KT))
            nisa.tensor_copy(dst=KV, src=kvi, engine=VE)
            RK = _sb((128, 1))
            dma_static(dst=RK, src=rank.ap(pattern=[[0, 128], [1, 1]], offset=0))
            for c in range(len(CLS)):  # one stacked selection, then the compaction, a class
                NT = CLS[c]
                NG = NT // PPP
                wio, po, TG, bits = _topk_consts(NT, 128, 7)
                posi = _sb((128, NT), I32)  # the pool of each tile entry: p NT + c, the tie order
                nisa.iota(dst=posi, pattern=[[1, NT]], offset=0, channel_multiplier=NT)
                POS = _sb((128, NT))
                nisa.tensor_copy(dst=POS, src=posi, engine=VE)
                O = _select2s(SSC[c], len(CROWS[c]), NT, TG, POS, keep, _nbits(NT * 128), rbits)
                nch = -(-NT // 128) if NT >= 128 else 1  # ceil: the last chunk _cwj(NT, nch - 1) wide
                if dbg == 1:  # the planted fault (tests only): sel2's chunk count, the partial chunk dropped
                    nch = NT // 128 if NT >= 128 else 1
                cw = 128 if NT >= 128 else NT
                UT = _sb((128, nch * NT), BF16)  # block j: [c', c] = (j cw + c' <= c), c' < cw, c < NT
                for j in range(nch):
                    dj = _sb((128, NT))
                    nisa.tensor_scalar(dst=dj, data=io512[:, 0:NT], op0=nl.subtract, operand0=pf_, op1=nl.subtract,
                                       operand1=float(j * cw), engine=VE)
                    nisa.tensor_scalar(dst=UT[:, j * NT:(j + 1) * NT], data=dj, op0=nl.greater_equal, operand0=0.0,
                                       engine=VE)
                SALLc = []
                bbc = []
                ii = []
                for j in range(len(CROWS[c])):
                    SALLc.append(SALL[CROWS[c][j]])
                    bbc.append(rows[CROWS[c][j]])
                    ii.append(j)
                XC = dict(NT=NT, NG=NG, NGM=NGM, B=B, keep=keep, KT=KT, nch=nch, cw=cw, A=A, O=O, SALL=SALLc, ppg=ppg,
                          IO512=io512, UPI=UPI, IF=IF, ONES1=ONES1, IB=IB, IOTA=io512[:, 0:128], IONT=io512[:, 0:NT],
                          IONG=io512[:, 0:NG], UT=UT, KV=KV, RK=RK, out=out, STG=STG, NP=len(rows), NPG=npg)
                if cs == 1 and len(ii) >= 4:  # cs 1, as sel2g's (>= 4 rows of the class a program)
                    _compact2sg(XC, ii, bbc)
                else:
                    _compact2g(XC, ii, bbc)
        if len(rows) > 0:  # the program's ONE store of out (its rows' slots, every plane)
            dma_static(dst=out.ap(pattern=[[128, KT], [B * keep, 3], [npg * keep, len(rows)], [1, 128]], offset=pid * keep),
                       src=STG)
        if npg > 1:
            nisa.core_barrier(data=out, cores=(0, 1))  # one output, one barrier (sel2g's)
        return out

    @nki.jit
    def dsa_sel2gc_kernel(qT, wb, pkc, ppg, cand, identb, rank, keep: int, A: int, nbits: int, rbits: int, rev: int,
                               dge: int = 0, nr: int = 4, qr: int = 4, pf: int = 2, cs: int = 0, dbg: int = 0):
        """sel2g's arguments (rev: revgc(B); dbg 1 sel2g's planted fault, tests only), the classes _rc_layout(B) (B the
        batch: cand's rows). Returns fp32 [3, B, keep] (sel2g's)."""
        return _sel2gc(qT, wb, pkc, ppg, cand, identb, rank, keep, A, nbits, rbits, rev, dge, nr, qr, pf, cs, dbg,
                       _rc_layout(cand.shape[0]))

else:
    dsa_sel2gc_kernel = None


def _revgc_base() -> int:
    """This module's kernel source and sel2's revision (REV2), one ordered hash: the compile-cache key does not hash NKI
    kernel source. A call adds its own batch size's layout term (revgc)."""
    import hashlib

    t = open(__file__).read()
    a = t.index("if nki is not None:  # sel2gc's kernel")
    b = t.index("    dsa_sel2gc_kernel = None", a)
    return int(hashlib.sha256(repr((t[a:b], dsh.REV2)).encode()).hexdigest()[:8], 16)


REVGC_BASE = _revgc_base()


def layout_crc(B: int) -> int:
    """B's OWN layout's share of the revision, so adding another batch size's layout moves no key of this one; 0 for a
    batch size without a layout. A dict lookup (traced code calls it)."""
    return _LAYOUT_CRC.get(int(B), 0)


def revgc(B: int) -> int:
    """sel2gc's revision for a call of B rows: REVGC_BASE and B's own layout only."""
    return REVGC_BASE ^ layout_crc(B)


def layout(rows: int):
    """The class layout (NG per slot) a batch of `rows` takes, or None."""
    return LAYOUTS.get(int(rows))


# The runner's guard: the engine's runner sets RUNNER (a name) once it orders every plain decode batch into the class
# slots (the longest rows in the widest slots) and sends a batch that does not fit() to the next page bucket. The kernel
# reads only a slot's first 128 NG_s pages, so without that guard a long row in a narrow slot would lose pages silently:
# until it is set, takes() is False and the decode takes the classless selection. set_layouts clears it.


def takes(rows: int, table: torch.Tensor) -> bool:
    """Whether a decode call of `rows` rows over `table` [rows, NPg] takes the classed selection: the runner's guard is
    in (RUNNER), and a layout for this batch size whose largest class is the bucket (NPg = 128 NGM)."""
    ngs = layout(rows)
    return RUNNER is not None and ngs is not None and table.shape[-1] == 128 * max(ngs)


def classed_ppg(table: torch.Tensor, ngs) -> torch.Tensor:
    """ppg int32 [128, B, NGM] for the classed kernel: slot s's page groups at its own NG_s (page p NG_s + g of the row at
    [p, s, g], g < NG_s) from its first 128 NG_s pages; the columns past NG_s are unread (left as dsa_index.page_groups).
    Functional (slices, permutes, one cat a run of equal-NG slots): no in-place write into a buffer the graph also reads."""
    from . import dsa_index

    NGM = table.shape[-1] // 128
    parts, s0 = [], 0
    for s in range(1, len(ngs) + 1):
        if s < len(ngs) and ngs[s] == ngs[s0]:
            continue
        g, run = ngs[s0], table[s0:s]
        if g < NGM:
            parts.append(torch.cat([dsa_index.page_groups(run[:, :128 * g]), dsa_index.page_groups(run)[:, :, g:]], dim=2))
        else:
            parts.append(dsa_index.page_groups(run))
        s0 = s
    return torch.cat(parts, dim=1).contiguous()


def fits(nloc: torch.Tensor, ngs) -> bool:
    """Whether every slot's visible pools lie in its first 128 NG_s pages (the classed kernel's precondition: the runner's
    guard sends a batch that doesn't fit to the next page bucket)."""
    cap = torch.tensor([128 * g * dsh.PPP for g in ngs], device=nloc.device, dtype=torch.int64)
    return bool((nloc.to(torch.int64).reshape(-1) <= cap).all())


def select2gc(q: torch.Tensor, w: torch.Tensor, pkc: torch.Tensor, table: torch.Tensor, nloc: torch.Tensor, keep: int,
              A: int, rank: torch.Tensor, *, rbits: int = 2, dge: int = 0, simulate: bool = False, grid: int | None = None,
              nr: int | None = None, pf: int = 2, cs: int = 0, dbg: int = 0, check: bool = True):
    """select2g's call and outputs with the classes layout(B): dsa_sel2gc_kernel on a device or in the simulator,
    emulate() on the host (the same bits: the classes change none). Refuses a layout-less batch or one that doesn't fit
    (check False: the caller guarantees the fit)."""
    from . import dsa_index

    B, Hi, _ = q.shape
    ngs = layout(B)
    if ngs is None or table.shape[-1] != 128 * max(ngs):  # takes() less the runner's guard: fits() below is this call's
        raise ValueError(f"select2gc: no class layout for B {B} at {table.shape[-1]} pages")
    if check and not fits(nloc, ngs):
        raise ValueError("select2gc: a row's visible pools pass its slot's class (the runner's guard)")
    if q.device.type == "cpu" and not simulate and not SH.HOST_SIM:
        lval, cpool, rows, _ = dsh.emulate(q, w, pkc, table, nloc, keep, A, int(rank.reshape(())))
        return lval, cpool, rows
    if dsa_sel2gc_kernel is None:
        raise RuntimeError("the NKI DSA selection needs the nki package (the Neuron venv)")
    if cs not in (0, 1) or dbg not in (0, 1):
        raise ValueError(f"select2gc: cs={cs}, dbg={dbg}: 0 or 1")
    if grid is None:
        from .. import platform

        grid = 1 if simulate else platform.nki_grid()
    NPg = table.shape[1]
    P = NPg * dsh.PPP
    if CW:  # the kernel builds the candidate bias from nloc (fp32 [B, 1]); no [B, P] mask in the graph
        cand = nloc.float().reshape(-1, 1)
    else:
        cand = torch.where(torch.arange(P, device=q.device).view(1, P) < nloc.view(-1, 1), 0.0, dsh.NEG_INF)
    args = dict(qT=q.to(torch.bfloat16).reshape(B * Hi, dsh.D).t().contiguous(),
                wb=w.float().repeat(1, 4).unsqueeze(1).expand(B, 128, 4 * Hi).contiguous(),
                pkc=pkc.to(torch.bfloat16), ppg=classed_ppg(table, ngs), cand=cand.float(),
                identb=torch.eye(128, device=q.device).to(torch.bfloat16), rank=rank.to(torch.float32).reshape(1, 1),
                keep=int(keep), A=int(A), nbits=int(P.bit_length()), rbits=int(rbits), rev=revgc(B), dge=int(dge),
                nr=dsa_index.NR if nr is None else int(nr), qr=dsa_index.QR, pf=int(pf), cs=int(cs), dbg=int(dbg))
    k = dsa_sel2gc_kernel
    if simulate:
        import os

        import ml_dtypes
        import numpy as np

        os.environ["NEURON_PLATFORM_TARGET_OVERRIDE"] = "trn2"  # an LNC=2 (trn2) kernel

        def to_np(t):
            if not isinstance(t, torch.Tensor):
                return t
            return t.float().numpy().astype(ml_dtypes.bfloat16) if t.dtype == torch.bfloat16 else t.numpy()

        o = nki.simulate(k[grid] if grid > 1 else k)(**{n: to_np(t) for n, t in args.items()})
        o = torch.from_numpy(np.asarray(o, dtype=np.float32))
        return o[0], o[1], o[2].to(torch.int32)
    from libtorch_neuronx_lite.nki.nki_hop import wrap_nki

    o = wrap_nki(k)[grid](**args)  # one output: wrap_nki returns a bare tensor
    return o[0], o[1], o[2].to(torch.int32)
